package io.github.nijasc.ktor.svelte.internal.typescript

internal const val PAGE_LOADS_FILE = "loads.ts"
internal const val PAGE_LOAD_PREFIX = "// Generated by ktor-svelte from pageLoad"
internal const val PAGE_LOAD_MARKER =
    "// Generated by ktor-svelte from pageLoad in Kotlin. Do not edit: change the pageLoad, or remove it to write this file yourself."

private val PAGE_PARAMETER = Regex("\\[([A-Za-z_][A-Za-z0-9_]*)]")
private val IDENTIFIER_START = Regex("^[A-Za-z_]")

internal class PageDataSpec(
    val key: String,
    val method: String,
    val path: String,
    val params: Map<String, String>,
) {
    val route: String get() = "$method $path"
}

internal class PageLoadSpec(
    val page: String,
    val data: List<PageDataSpec>,
)

internal fun pageParameters(page: String): List<String> = PAGE_PARAMETER.findAll(page).map { it.groupValues[1] }.toList()

internal fun pageLoadFunction(page: String): String {
    val words =
        page
            .split(Regex("[^A-Za-z0-9]+"))
            .filter { it.isNotEmpty() }
            .joinToString("") { word -> word.replaceFirstChar { it.uppercaseChar() } }
    return "load" + words.ifEmpty { "Home" }
}

internal fun pageModuleSource(page: String): String =
    "$PAGE_LOAD_MARKER\n" +
        "import { ${pageLoadFunction(page)} } from '#api';\n" +
        "import type { PageLoad } from './\$types';\n\n" +
        "export const load: PageLoad = (event) => ${pageLoadFunction(page)}(event);\n"

internal fun pageLoadsSource(
    pages: List<PageLoadSpec>,
    operations: List<GeneratedOperation>,
): String {
    val byRoute = operations.associateBy { "${it.method} ${it.path}" }
    pages.groupBy { pageLoadFunction(it.page) }.values.firstOrNull { it.size > 1 }?.let { same ->
        error("The pages ${same.joinToString(" and ") { "'${it.page}'" }} would both get the load ${pageLoadFunction(same.first().page)}.")
    }
    val functions =
        pages.sortedBy { it.page }.joinToString("\n") { page ->
            val parameters = pageParameters(page.page)
            val calls =
                page.data.map { data ->
                    val operation =
                        byRoute[data.route]
                            ?: error(
                                "pageLoad: '${page.page}' loads ${data.route}, which is not part of the generated client. " +
                                    "Only routes under the API prefixes can be loaded.",
                            )
                    check(!operation.needsInput) {
                        "pageLoad: ${data.route} needs a body, query or header that a page load cannot fill. " +
                            "Write the load of '${page.page}' yourself."
                    }
                    val arguments =
                        operation.pathParameters.mapIndexed { index, name ->
                            val from = data.params[name] ?: name
                            check(from in parameters) {
                                "pageLoad: ${data.route} needs the path parameter '$name', and the page '${page.page}' has " +
                                    (if (parameters.isEmpty()) "none" else parameters.joinToString { "[$it]" }) +
                                    ". Map it with params = mapOf(\"$name\" to \"<page parameter>\")."
                            }
                            val value = "event.params.$from"
                            if (operation.pathTypes.getOrNull(index) == "number") "Number($value)" else value
                        } + List(operation.optionalSlots) { "undefined" } + "{ silent: true }"
                    "        api.${operation.name}(${arguments.joinToString()})"
                }
            val keys = page.data.map { it.key }
            val params = if (parameters.isEmpty()) "" else "; params: { ${parameters.joinToString("; ") { "$it: string" }} }"
            "export async function ${pageLoadFunction(page.page)}(event: { fetch: typeof fetch; url: URL$params }) {\n" +
                "    const api = apiWith(event);\n" +
                "    const load = () =>\n" +
                "        Promise.all([\n" +
                calls.joinToString(",\n") { "    $it" } + "\n" +
                "        ]);\n" +
                "    const inline = inlinePageData(event.url.pathname);\n" +
                "    const [${keys.joinToString()}] = inline\n" +
                "        ? (${keys.joinToString(", ", "[", "]") { "inline.$it" }} as Awaited<ReturnType<typeof load>>)\n" +
                "        : await load();\n" +
                "    return { ${keys.joinToString()} };\n" +
                "}\n"
        }
    return "import { inlinePageData } from './client.js';\nimport { apiWith } from './services.js';\n\n$functions"
}

internal fun validPageDataKey(key: String): Boolean = IDENTIFIER_START.containsMatchIn(key) && key.all { it.isLetterOrDigit() || it == '_' }
